function initials(n){const p=n.trim().split(" ");return(p[0][0]+(p[1]?p[1][0]:"")).toUpperCase();}
function fmtBRL(v){return"R$ "+Number(v).toLocaleString("pt-BR",{minimumFractionDigits:2,maximumFractionDigits:2});}
function calcBgtTotal(b){if(b.priceMode==="split")return(b.labor||0)+(b.material||0);if(b.priceMode==="total")return b.total||0;if(b.items&&b.items.length)return b.items.reduce((a,it)=>a+(it.qty*it.val),0);return 0;}
function sendWpp(phone,msg){window.open("https://wa.me/"+(phone||"").replace(/\D/g,"")+"?text="+encodeURIComponent(msg),"_blank");}
function openMaps(addr){window.open("https://maps.google.com/?q="+encodeURIComponent(addr),"_blank");}

// ===================== TOAST =====================
function Toast({msg,type}){
  return msg?<div style={{position:"fixed",top:18,left:"50%",transform:"translateX(-50%)",background:"#111",border:`1px solid ${type==="ok"?"#3EC97A":"#FBBC05"}`,color:type==="ok"?"#3EC97A":"#FBBC05",borderRadius:28,padding:"9px 18px",fontSize:12,fontWeight:600,zIndex:200,whiteSpace:"nowrap"}}>{msg}</div>:null;
}

// ===================== MODAL =====================
function Modal({id,title,open,onClose,children}){
  if(!open)return null;
  return(
    <div onClick={e=>{if(e.target===e.currentTarget)onClose();}} style={{position:"fixed",inset:0,background:"rgba(0,0,0,.84)",zIndex:50,display:"flex",alignItems:"flex-end"}}>
      <div style={{background:"#111",borderRadius:"20px 20px 0 0",borderTop:"1px solid rgba(255,255,255,.07)",width:"100%",maxHeight:"92vh",overflowY:"auto",paddingBottom:"env(safe-area-inset-bottom,18px)",animation:"slideUp .27s ease"}}>
        <div style={{width:32,height:3,background:"rgba(255,255,255,.07)",borderRadius:2,margin:"10px auto 6px"}}/>
        <div style={{padding:"5px 16px 13px",display:"flex",alignItems:"center",justifyContent:"space-between",borderBottom:"1px solid rgba(255,255,255,.07)"}}>
          <span style={{fontSize:16,fontWeight:700}}>{title}</span>
          <span onClick={onClose} style={{fontSize:17,color:"#888",cursor:"pointer",padding:4}}>✕</span>
        </div>
        <div style={{padding:16}}>{children}</div>
      </div>
    </div>
  );
}

// ===================== PILL =====================
const PILL_MAP={active:{bg:"rgba(62,201,122,.12)",color:"#3EC97A",label:"Em andamento"},pending:{bg:"rgba(251,188,5,.12)",color:"#FBBC05",label:"Pendente"},done:{bg:"rgba(136,136,136,.12)",color:"#888",label:"Concluído"},sched_no_date:{bg:"rgba(74,158,255,.12)",color:"#4A9EFF",label:"Ag. sem data"},pendente:{bg:"rgba(251,188,5,.12)",color:"#FBBC05",label:"Pendente"},aprovado:{bg:"rgba(62,201,122,.12)",color:"#3EC97A",label:"Aprovado"},recusado:{bg:"rgba(224,82,82,.12)",color:"#E05252",label:"Recusado"},concluido:{bg:"rgba(136,136,136,.12)",color:"#888",label:"Concluído"}};
function Pill({status}){const p=PILL_MAP[status]||PILL_MAP.pending;return<span style={{fontSize:9,fontWeight:700,padding:"3px 7px",borderRadius:20,background:p.bg,color:p.color,whiteSpace:"nowrap"}}>{p.label}</span>;}

// ===================== BTN =====================
function Btn({children,onClick,style={},variant="primary"}){
  const base={width:"100%",padding:"13px 14px",borderRadius:10,fontFamily:"inherit",fontSize:14,fontWeight:700,cursor:"pointer",border:"none",display:"flex",alignItems:"center",justifyContent:"center",gap:6,transition:"opacity .15s"};
  const variants={primary:{background:"#FBBC05",color:"#000"},secondary:{background:"#181818",color:"#F2EFE9",border:"1px solid rgba(255,255,255,.07)"},green:{background:"rgba(62,201,122,.15)",color:"#3EC97A"},red:{background:"rgba(224,82,82,.15)",color:"#E05252"},wpp:{background:"#25D366",color:"#000"}};
  return<button onClick={onClick} style={{...base,...(variants[variant]||variants.primary),...style}}>{children}</button>;
}

// ===================== FIELD =====================
function Field({label,children}){return<div style={{marginBottom:13}}><label style={{display:"block",fontSize:11,color:"#888",fontWeight:600,letterSpacing:.5,textTransform:"uppercase",marginBottom:5}}>{label}</label>{children}</div>;}
function Input(props){return<input {...props} style={{width:"100%",background:"#181818",border:"1px solid rgba(255,255,255,.07)",borderRadius:10,padding:"11px 13px",color:"#F2EFE9",fontSize:14,fontFamily:"inherit",outline:"none",...(props.style||{})}}/>;}

// ===================== PAY CHIPS =====================
function PayChips({value,onChange}){
  const opts=[["dinheiro","💵 Dinheiro"],["pix","⚡ PIX"],["cartao","💳 Cartão"],["transferencia","🏦 Transferência"]];
  return<div style={{display:"flex",gap:7,flexWrap:"wrap",marginTop:7}}>{opts.map(([v,l])=><div key={v} onClick={()=>onChange(v)} style={{padding:"6px 11px",borderRadius:20,fontSize:12,fontWeight:600,border:`1px solid ${value===v?"#FBBC05":"rgba(255,255,255,.07)"}`,background:value===v?"rgba(251,188,5,.13)":"#181818",color:value===v?"#FBBC05":"#888",cursor:"pointer"}}>{l}</div>)}</div>;
}

// ===================== SECTION BOX =====================
function SBox({title,children}){return<div style={{background:"#242424",borderRadius:12,padding:13,marginBottom:11}}><div style={{fontSize:12,fontWeight:700,color:"#FBBC05",marginBottom:9}}>{title}</div>{children}</div>;}

// ===================== CHECKLIST =====================
function Checklist({items,onChange}){
  return<div>{items.map((c,i)=><div key={i} onClick={()=>{const n=[...items];n[i]={...n[i],d:!n[i].d};onChange(n);}} style={{display:"flex",alignItems:"center",gap:10,padding:"9px 0",borderBottom:"1px solid rgba(255,255,255,.07)",cursor:"pointer"}}>
    <div style={{width:20,height:20,borderRadius:"50%",border:`2px solid ${c.d?"#3EC97A":"#4a4a4a"}`,background:c.d?"#3EC97A":"transparent",display:"flex",alignItems:"center",justifyContent:"center",fontSize:10,flexShrink:0,color:"#000"}}>{c.d?"✓":""}</div>
    <span style={{fontSize:13,textDecoration:c.d?"line-through":"none",color:c.d?"#888":"#F2EFE9"}}>{c.t}</span>
  </div>)}</div>;
}

