// --- ONBOARDING ---
const OB_SLIDES=[
  {icon:"📱",title:<>Pare de perder clientes <span style={{color:"#FBBC05"}}>no WhatsApp.</span></>,text:"Gerencie todos os seus clientes e contatos em um só lugar. Rápido, simples e profissional."},
  {icon:"📄",title:<>Crie orçamentos <span style={{color:"#FBBC05"}}>em segundos.</span></>,text:"Monte orçamentos profissionais com sua logo e envie pelo WhatsApp. Mostre que você é diferenciado."},
  {icon:"⚡",title:<>Agenda, clientes e <span style={{color:"#FBBC05"}}>pagamentos.</span></>,text:"Tudo organizado num app feito para eletricistas. Sem complicação, sem planilha, sem bagunça."}
];
function OnboardScreen({onFinish}){
  const [slide,setSlide]=useState(0);
  const s=OB_SLIDES[slide];
  return(
    <div style={{minHeight:"100vh",background:"#0a0a0a",padding:"64px 26px 48px",display:"flex",flexDirection:"column",justifyContent:"space-between"}}>
      <div>
        <div style={{width:72,height:72,background:"rgba(251,188,5,.13)",border:"1px solid rgba(251,188,5,.22)",borderRadius:18,display:"flex",alignItems:"center",justifyContent:"center",fontSize:30,marginBottom:26}}>{s.icon}</div>
        <h2 style={{fontSize:24,fontWeight:700,lineHeight:1.25,marginBottom:11}}>{s.title}</h2>
        <p style={{color:"#888",fontSize:14,lineHeight:1.65}}>{s.text}</p>
      </div>
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between"}}>
        <div style={{display:"flex",gap:5}}>{OB_SLIDES.map((_,i)=><div key={i} style={{width:i===slide?20:6,height:6,borderRadius:i===slide?3:"50%",background:i===slide?"#FBBC05":"#4a4a4a",transition:"all .3s"}}/>)}</div>
        <Btn onClick={()=>slide<2?setSlide(slide+1):onFinish()} style={{width:"auto",padding:"12px 28px"}}>{slide<2?"Próximo →":"Começar ⚡"}</Btn>
      </div>
    </div>
  );
}

